"""Build the shared, documented parameter catalogue used by BOTH languages."""
import json
from pathlib import Path

rows = []
def add(group, key, value, unit, description, low=None, high=None, choices=None):
    rows.append(dict(group=group, key=key, default=value, unit=unit,
                     description=description, minimum=low, maximum=high,
                     choices=choices or [], integer=isinstance(value, int)))

add('Run', 'channel', 'Fiber', '-', 'Propagation model to study.', choices=['Fiber','FSO-Terrestrial','Satellite-Ground'])
add('Run', 'seed', 7, '-', 'Repeatable random seed; streams differ between Python and Octave.', 0, 2**31-1)
add('Run', 'n_slots', 200000, 'slots', 'Number of valid adjacent-pulse detection opportunities; N+1 pulses are sent.', 100, 2000000)
add('Run', 'block_slots', 1000, 'slots', 'Independent piecewise-constant atmospheric blocks. Set from coherence time times clock rate.', 1, 2000000)
add('Run', 'fading_model', 'auto', '-', 'Auto: lognormal for Rytov variance <1, gamma-gamma otherwise. None disables scintillation only.', choices=['auto','none','lognormal','gamma-gamma'])
add('Run', 'sample_hex', 'A5 3C 7E 81 00 FF', 'hex bytes', 'Teaching example: bytes become pulse phase bits; adjacent XORs become key bits.')
add('Source', 'mu', 0.2, 'photons/pulse', 'Mean photon number of each emitted coherent pulse.', 0, 2)
add('Source', 'wavelength_nm', 1550.0, 'nm', 'Vacuum wavelength; all physics converts to metres.', 300, 2500)
add('Source', 'clock_hz', 1e9, 'Hz', 'Pulse clock; time-bin separation is its reciprocal.', 1, 1e11)
