add('Source', 'spectral_sigma_nm', 0.02, 'nm', 'RMS optical spectral width for the simplified fiber dispersion model.', 0, 100)
add('Receiver', 'detector_eta', 0.65, '-', 'Photon detection efficiency.', 0, 1)
add('Receiver', 'coupling_eta', 0.75, '-', 'Additional spatial mode coupling efficiency.', 0, 1)
