add('Fiber', 'dispersion_ps_nm_km', 17.0, 'ps/(nm km)', 'Chromatic dispersion coefficient; only RMS broadening/gate capture is modeled.', -1000, 1000)
add('FSO-Terrestrial', 'fso_km', 2.0, 'km', 'Horizontal free-space path.', 0.001, 100)
