add('Sweeps', 'sweep_points', 16, '-', 'Number of points in each channel-distance and Eve sweep.', 3, 100)
add('Sweeps', 'sweep_slots', 20000, 'slots', 'Monte Carlo averaging opportunities per sweep point.', 1000, 200000)
add('Sweeps', 'fiber_sweep_max_km', 200.0, 'km', 'Upper fiber distance in the channel sweep.', 1, 1000)
add('Sweeps', 'fso_sweep_max_km', 10.0, 'km', 'Upper horizontal FSO distance in the channel sweep.', 0.1, 100)

if __name__ == '__main__':
    Path(__file__).with_name('parameters.json').write_text(json.dumps(rows, indent=2)+'\n', encoding='utf-8')
    print(f'Wrote {len(rows)} parameter definitions.')
